package com.nbi.statusx.service;

import com.nbi.statusx.dto.PaymentRequest;
import com.nbi.statusx.exception.DailyLimitExceededException;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;

@Service
public class PaymentService {
    private static final BigDecimal DAILY_LIMIT = new BigDecimal("500000");
    private boolean ledgerUp = true; // toggled to simulate dependency down

    public String pay(PaymentRequest r) {
        // Well-formed but violates a BUSINESS rule → 422, NOT 400.
        if (r.amount().compareTo(DAILY_LIMIT) > 0)
            throw new DailyLimitExceededException("Exceeds daily limit of Rs.500000");
        return "PAY-" + System.nanoTime();
    }

    public boolean isLedgerUp() { return ledgerUp; }
    public void setLedgerUp(boolean up) { this.ledgerUp = up; }
}
