package com.nbi.statusx.exception;

import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.bind.MethodArgumentNotValidException;

@RestControllerAdvice
public class GlobalExceptionHandler {

    // Malformed / basic validation failure → 400 Bad Request
    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<String> malformed(MethodArgumentNotValidException e) {
        return ResponseEntity.badRequest().body("Malformed request"); // 400
    }

    // Well-formed but business-rule failure → 422 Unprocessable Entity
    @ExceptionHandler(DailyLimitExceededException.class)
    public ResponseEntity<String> businessRule(DailyLimitExceededException e) {
        return ResponseEntity.status(HttpStatus.UNPROCESSABLE_ENTITY).body(e.getMessage()); // 422
    }
}
